using System.ComponentModel.DataAnnotations;
namespace SimplexLawFirm.Models;
public enum FeeDiscountStatus { PendingDirector, AutomaticallyApproved, Approved, Rejected, CounterOffered, AcceptedCounterOffer }
public sealed class FeeDiscountPolicy { public int Id { get; set; } [MaxLength(120)] public string MatterType { get; set; } = "General"; public decimal MinimumRecoveryPercent { get; set; } = 70; public decimal AutomaticApprovalPercent { get; set; } = 10; public DateTime UpdatedAtUtc { get; set; } = DateTime.UtcNow; public int? UpdatedByUserId { get; set; } }
public sealed class FeeDiscountRequest { public int Id { get; set; } public int InvoiceId { get; set; } public Invoice Invoice { get; set; } = null!; public int ClientId { get; set; } public Client Client { get; set; } = null!; public decimal OriginalAmount { get; set; } public decimal ProposedAmount { get; set; } public decimal DiscountPercent { get; set; } [MaxLength(2000)] public string Reason { get; set; } = ""; public decimal MinimumRecoveryPercentSnapshot { get; set; } public decimal AutomaticApprovalPercentSnapshot { get; set; } [MaxLength(40)] public string PaymentReliability { get; set; } = ""; [MaxLength(2000)] public string Recommendation { get; set; } = ""; public FeeDiscountStatus Status { get; set; } public decimal? CounterOfferAmount { get; set; } public int? DecidedByUserId { get; set; } [MaxLength(2000)] public string? DecisionReason { get; set; } public DateTime CreatedAtUtc { get; set; } = DateTime.UtcNow; public DateTime? DecidedAtUtc { get; set; } }
